'use client';

import type * as React from 'react';
import { CheckIcon, MinusIcon, XIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import { useControllableState } from '@/hooks/use-controllable-state';
import { formatMoney } from '@/lib/money';
import type { BillingInterval, PlanView } from '@/types/billing-ui';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { BillingIntervalToggle } from './billing-interval-toggle';

export type ComparisonCell = boolean | 'partial' | string;

export interface ComparisonFeatureRow {
  id: string;
  label: string;
  /** Values keyed by plan id. true/false/'partial'/custom label */
  values: Record<string, ComparisonCell>;
}

export interface PlanComparisonProps extends React.ComponentProps<'div'> {
  plans: PlanView[];
  /** Explicit matrix rows. If omitted, derived from union of plan.features. */
  features?: ComparisonFeatureRow[];
  /** Controlled interval. */
  interval?: BillingInterval;
  defaultInterval?: BillingInterval;
  onIntervalChange?: (interval: BillingInterval) => void;
  /** Show Monthly/Yearly toggle above the matrix. */
  showIntervalToggle?: boolean;
  currencyFallback?: string;
  onSelectPlan?: (planId: string) => void;
  ariaLabel?: string;
  emptyMessage?: string;
}

function deriveFeatures(plans: PlanView[]): ComparisonFeatureRow[] {
  const order: string[] = [];
  const labels = new Map<string, string>();

  for (const plan of plans) {
    for (const f of plan.features) {
      if (!labels.has(f.id)) {
        labels.set(f.id, f.label);
        order.push(f.id);
      }
    }
  }

  return order.map((id) => ({
    id,
    label: labels.get(id) ?? id,
    values: Object.fromEntries(
      plans.map((plan) => {
        const hit = plan.features.find((f) => f.id === id);
        if (!hit) return [plan.id, false] as const;
        return [plan.id, hit.included === false ? false : true] as const;
      }),
    ),
  }));
}

function CellValue({ value }: { value: ComparisonCell }) {
  if (value === true) {
    return <CheckIcon className="mx-auto size-4 text-success" aria-label="Included" />;
  }
  if (value === false) {
    return <XIcon className="mx-auto size-4 text-muted-foreground/45" aria-label="Not included" />;
  }
  if (value === 'partial') {
    return <MinusIcon className="mx-auto size-4 text-muted-foreground" aria-label="Partial" />;
  }
  return <span className="text-sm text-foreground">{value}</span>;
}

/**
 * Feature × plan comparison matrix for marketing / docs pricing pages.
 */
export function PlanComparison({
  plans,
  features,
  interval: controlledInterval,
  defaultInterval = 'month',
  onIntervalChange,
  showIntervalToggle = false,
  currencyFallback = 'IDR',
  onSelectPlan,
  ariaLabel = 'Plan comparison',
  emptyMessage = 'No plans to compare.',
  className,
  ...props
}: PlanComparisonProps) {
  const [interval, setIntervalValue] = useControllableState(
    controlledInterval,
    defaultInterval,
    onIntervalChange,
  );

  if (plans.length === 0) {
    return (
      <div
        data-slot="plan-comparison-empty"
        className={cn(
          'rounded-lg border border-border bg-card p-6 text-sm text-muted-foreground shadow-none ring-1 ring-border',
          className,
        )}
        {...props}
      >
        {emptyMessage}
      </div>
    );
  }

  const rows = features ?? deriveFeatures(plans);

  const gridCols = {
    gridTemplateColumns: `minmax(8.5rem,1.2fr) repeat(${plans.length}, minmax(6.5rem,1fr))`,
  } as const;

  return (
    <div
      data-slot="plan-comparison"
      className={cn('@container flex w-full min-w-0 flex-col gap-3', className)}
      {...props}
    >
      {showIntervalToggle ? (
        <div className="flex w-full min-w-0 justify-stretch @md:justify-end">
          <BillingIntervalToggle
            value={interval}
            onChange={setIntervalValue}
            className="w-full @md:w-auto"
          />
        </div>
      ) : null}

      <div
        role="table"
        aria-label={ariaLabel}
        className="w-full min-w-0 overflow-hidden rounded-lg border border-border bg-card text-card-foreground shadow-none ring-1 ring-border"
      >
        <div
          role="rowgroup"
          className="overflow-x-auto overscroll-x-contain [-webkit-overflow-scrolling:touch]"
        >
          <div
            role="row"
            className="grid w-max min-w-[28rem] border-b border-border bg-muted/40 @lg:w-full @lg:min-w-0"
            style={gridCols}
          >
            <div
              role="columnheader"
              className="sticky left-0 z-10 bg-muted/95 p-3 text-left text-xs font-medium text-muted-foreground backdrop-blur-sm"
            >
              Feature
            </div>
            {plans.map((plan) => {
              const currency = plan.currency ?? currencyFallback;
              const amount = interval === 'year' ? plan.yearlyAmount : plan.monthlyAmount;
              return (
                <div
                  key={plan.id}
                  role="columnheader"
                  className={cn(
                    'flex flex-col items-center gap-2 border-l border-border p-2.5 text-center sm:p-3',
                    plan.recommended && 'bg-primary/5',
                  )}
                >
                  <div className="flex flex-wrap items-center justify-center gap-1.5">
                    <span className="text-sm font-semibold">{plan.name}</span>
                    {plan.recommended ? <Badge tone="default">Popular</Badge> : null}
                  </div>
                  <span className="text-sm font-medium tabular-nums">
                    {formatMoney(amount, { currency })}
                    <span className="font-normal text-muted-foreground">
                      {interval === 'year' ? '/yr' : '/mo'}
                    </span>
                  </span>
                  {onSelectPlan ? (
                    <Button
                      size="xs"
                      variant={plan.recommended ? 'default' : 'outline'}
                      onClick={() => onSelectPlan(plan.id)}
                    >
                      {plan.ctaLabel ?? 'Select'}
                    </Button>
                  ) : null}
                </div>
              );
            })}
          </div>

          {rows.map((row, i) => (
            <div
              key={row.id}
              role="row"
              className={cn(
                'grid w-max min-w-[28rem] border-b border-border last:border-b-0 @lg:w-full @lg:min-w-0',
                i % 2 === 1 && 'bg-muted/20',
              )}
              style={gridCols}
            >
              <div
                role="cell"
                className={cn(
                  'sticky left-0 z-10 max-w-[10rem] p-2.5 text-left text-sm text-foreground @sm:max-w-none @sm:p-3',
                  i % 2 === 1 ? 'bg-muted/90 backdrop-blur-sm' : 'bg-card/95 backdrop-blur-sm',
                )}
              >
                {row.label}
              </div>
              {plans.map((plan) => (
                <div
                  key={plan.id}
                  role="cell"
                  className={cn(
                    'flex items-center justify-center border-l border-border p-2.5 sm:p-3',
                    plan.recommended && 'bg-primary/[0.03]',
                  )}
                >
                  <CellValue value={row.values[plan.id] ?? false} />
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
